package com.fit100.tracker
import android.Manifest
import android.app.*
import android.content.*
import android.content.pm.PackageManager
import android.content.res.ColorStateList
import android.graphics.*
import android.graphics.drawable.GradientDrawable
import android.os.*
import android.text.InputType
import android.view.*
import android.widget.*
import java.time.*
import java.time.format.DateTimeFormatter
import kotlin.math.*

class WorkoutDashboard(private val a:Activity,private val p:SharedPreferences,private val page:LinearLayout,private val refresh:()->Unit) {
 private val repo=SportsHub.repo(a);private val lime=Color.rgb(156,255,69);private val white=Color.rgb(246,251,246);private val muted=Color.rgb(167,190,173);private val today=LocalDate.now()
 private val compact get()=a.resources.configuration.screenWidthDp<360||a.resources.configuration.fontScale>1.2f
 private fun now()=SportsHub.now(a)
 private fun dp(v:Int)=(v*a.resources.displayMetrics.density).toInt()
 private fun bg(color:Int=Color.rgb(16,35,24))=GradientDrawable().apply { setColor(color);cornerRadius=dp(15).toFloat();setStroke(dp(1),Color.rgb(39,64,45)) }
 private fun text(s:String,size:Float=14f,color:Int=white,bold:Boolean=false)=TextView(a).apply { text=s;textSize=size;setTextColor(color);if(bold)setTypeface(null,Typeface.BOLD);setPadding(0,dp(3),0,dp(3)) }
 private fun col()=LinearLayout(a).apply { orientation=1 }
 private fun add(parent:LinearLayout,v:View,top:Int=8){parent.addView(v,LinearLayout.LayoutParams(-1,-2).apply { topMargin=dp(top) })}
 private fun card(title:String,parent:LinearLayout=page)=col().apply { background=bg();setPadding(dp(14),dp(12),dp(14),dp(14));add(parent,this);if(title.isNotBlank())add(this,text(title,18f,white,true),0) }
 private fun button(parent:LinearLayout,label:String,primary:Boolean=false,action:()->Unit)=Button(a).apply { text=label;isAllCaps=false;textSize=14f;setTextColor(if(primary)Color.rgb(6,20,12) else white);background=bg(if(primary)lime else Color.rgb(9,28,17));minimumHeight=dp(48);contentDescription=label;setOnClickListener { action() };add(parent,this) }
 private fun note(parent:LinearLayout,s:String)=add(parent,text(s,12f,muted))
 private fun input(parent:LinearLayout,label:String,value:String="",decimal:Boolean=false):EditText {note(parent,label);return EditText(a).apply { setText(value);setTextColor(white);setHintTextColor(muted);backgroundTintList=ColorStateList.valueOf(lime);minimumHeight=dp(48);if(decimal)inputType=InputType.TYPE_CLASS_NUMBER or InputType.TYPE_NUMBER_FLAG_DECIMAL;contentDescription=label;setSingleLine();add(parent,this) } }
 private fun go(screen:String){p.edit().putString("workout-screen",screen).apply();refresh()}
 private fun toast(s:String)=Toast.makeText(a,s,Toast.LENGTH_SHORT).show()
 private fun confirm(title:String,message:String,action:()->Unit){AlertDialog.Builder(a).setTitle(title).setMessage(message).setNegativeButton("Cancel",null).setPositiveButton("Confirm"){_,_->action()}.show()}
 private fun dialog(title:String,build:(LinearLayout)->(() -> Boolean)){val content=col().apply { setPadding(dp(20),dp(8),dp(20),dp(12));background=bg() };val save=build(content);val d=AlertDialog.Builder(a).setTitle(title).setView(ScrollView(a).apply { addView(content) }).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.setOnShowListener { d.getButton(-1).setOnClickListener { if(save())d.dismiss() } };d.show() }
 private fun live(view:TextView,read:()->String){val h=Handler(Looper.getMainLooper());val tick=object:Runnable {override fun run(){if(!view.isAttachedToWindow)return;view.text=read();h.postDelayed(this,500)}};view.addOnAttachStateChangeListener(object:View.OnAttachStateChangeListener {override fun onViewAttachedToWindow(v:View){h.post(tick)};override fun onViewDetachedFromWindow(v:View){h.removeCallbacks(tick)}});view.text=read()}
 private fun duration(ms:Long):String {val sec=ms.coerceAtLeast(0)/1000;return "%02d:%02d:%02d".format(sec/3600,sec/60%60,sec%60)}
 private fun exerciseDistance(s:SportsSession,id:String):Double? {val segments=s.distances;if(segments!=null)return s.items.indices.filter { s.items[it].target.id==id }.mapNotNull { segments[it] }.takeIf { it.isNotEmpty() }?.sum();return s.distance?.takeIf { (s.items.size==1&&s.items[0].target.id==id)||(s.items.isEmpty()&&s.name.equals(if(id=="walking")"Walking" else "Jogging",true)) } }
 private fun km(m:Double?)=m?.let { "%.2f km".format(it/1000) }?:"Unavailable"
 private fun calories(s:SportsSession)=s.calories?:SportsEngine.estimate(s,now())
 private fun kcal(v:Double?)=v?.let { "%.0f kcal est.".format(it) }?:"Unavailable · add weight"
 private fun bar(parent:LinearLayout,percent:Int){add(parent,ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal).apply { max=100;progress=percent.coerceIn(0,100);progressTintList=ColorStateList.valueOf(lime);progressBackgroundTintList=ColorStateList.valueOf(Color.rgb(40,61,46));contentDescription="$percent percent complete" })}
 private fun art(parent:LinearLayout,id:String,height:Int=160){parent.addView(SportsExerciseArt(a,id),LinearLayout.LayoutParams(-1,dp(height)).apply { topMargin=dp(8) })}
 private fun weight()=p.getString("$today-weight",null)?.toDoubleOrNull()?.takeIf { it in 20.0..500.0 }?:p.getString("profile-currentweight",null)?.toDoubleOrNull()?.takeIf { it in 20.0..500.0 }
 private fun range(history:List<SportsSession>,filter:String)=history.filter { when(filter){"Today"->it.date==today;"Week","This Week"->it.date>=today.with(java.time.temporal.TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY))&&it.date<=today;"Month"->it.date>=today.minusDays(29)&&it.date<=today;else->true} }
 private fun tabs(parent:LinearLayout,items:List<String>,selected:String,action:(String)->Unit){val row=LinearLayout(a);val scroll=HorizontalScrollView(a).apply { isHorizontalScrollBarEnabled=false;addView(row) };add(parent,scroll);items.forEach { name->row.addView(Button(a).apply { text=name;isAllCaps=false;textSize=12f;setTextColor(if(name==selected)Color.BLACK else white);background=bg(if(name==selected)lime else Color.rgb(11,31,19));setOnClickListener { action(name) } },LinearLayout.LayoutParams(-2,dp(48)).apply { marginEnd=dp(5) }) } }
 fun render(){val screen=p.getString("workout-screen","Workout")?:"Workout"
  if(screen in listOf("Workout","Exercises","Plans","Activity","Activity Log","Stats"))tabs(page,listOf("Workout","Exercises","Plans","Activity","Stats"),screen){go(it)}
  when {screen=="Workout"->home();screen=="Exercises"->library();screen=="Plans"->plans();screen=="Activity"||screen=="Activity Log"->history();screen=="Stats"->analytics();screen=="Rest Day"->recovery();screen=="Settings"->settings();screen=="Session"->tracker();screen=="Summary"->summary();screen.startsWith("History:")->historyDetail(screen.removePrefix("History:"));screen.startsWith("Exercise:")->exerciseSetup(screen.removePrefix("Exercise:"));else->home()}
 }
 private fun home(){val heading=LinearLayout(a).apply { gravity=Gravity.CENTER_VERTICAL };heading.addView(text("Sports",22f,white,true),LinearLayout.LayoutParams(0,-2,1f));heading.addView(text("${SportsHub.streak(a)} day streak",13f,lime));heading.addView(Button(a).apply { text="Settings";isAllCaps=false;setTextColor(lime);background=bg();textSize=11f;contentDescription="Sports settings";setOnClickListener { go("Settings") } },LinearLayout.LayoutParams(dp(76),dp(48)));add(page,heading)
  val stats=card("Today’s Activity");val line=LinearLayout(a).apply { gravity=Gravity.CENTER_VERTICAL };val ring=text("",19f,lime,true).apply { gravity=Gravity.CENTER };line.addView(ring,LinearLayout.LayoutParams(dp(112),dp(112)));val values=text("",14f);line.addView(values,LinearLayout.LayoutParams(0,-2,1f).apply { marginStart=dp(14) });add(stats,line)
  live(ring){val steps=SportsHub.dailySteps(a);val goal=p.getInt("sports-step-goal",10000);ring.background=HomeArt("ring",(steps?:0).toFloat()/goal,lime);"${steps?.toString()?:"—"}\n/ $goal"}
  live(values){val all=repo.history().filter { it.date==today };val active=repo.active()?.takeIf { it.date==today&&it.status!="REVIEW" };val ms=all.sumOf { it.timer.accumulated }+(active?.timer?.elapsed(now())?:0);val dist=all.mapNotNull { it.distance }+listOfNotNull(active?.distance);val estimates=all.mapNotNull { it.calories }+listOfNotNull(active?.let { SportsEngine.estimate(it,now()) });"${if(dist.isEmpty())"—" else "%.2f".format(dist.sum()/1000)} km distance\n${ms/60000} active min\n${if(estimates.isEmpty())"—" else "%.0f".format(estimates.sum())} kcal estimated"}
  note(stats,if(SportsHub.dailySteps(a)==null)"No step data yet. Enable sensor access in Settings or log a measured activity." else "Sensor and manual entries. Calories are estimates.")
  val plan=repo.plan(today.dayOfWeek.value);val active=repo.active();val workout=card("Today’s Workout");add(workout,text(plan.name,23f,lime,true));note(workout,if(plan.recovery)"Planned recovery · gentle activity is optional" else "${plan.exercises.size} exercises · ${plan.exercises.sumOf { it.sets*(it.rest+45) }/60} min suggested · ${p.getString("profile-workout-type","Mixed")}")
  val completed=repo.history().filter { it.date==today&&it.name==plan.name }.maxByOrNull { it.started };val percent=completed?.completion?:active?.takeIf { it.name==plan.name }?.completion?:0;bar(workout,percent);note(workout,"${completed?.completedExercises?:active?.takeIf { it.name==plan.name }?.completedExercises?:0} / ${plan.exercises.size} exercises completed · $percent%")
  button(workout,when {active?.status=="REVIEW"->"Review Unsaved Workout";active!=null->"Resume ${active.name}";plan.recovery->"Open Rest Day";else->"Start Workout →"},true){if(active!=null)go(if(active.status=="REVIEW")"Summary" else "Session") else if(plan.recovery)go("Rest Day") else startPlan(plan)}
  add(page,text("Exercise Options",19f,white,true));gridExercises(page,SportsExercises.all)
  val week=range(repo.history(),"Week");val weekly=card("Weekly Activity");val monday=today.with(java.time.temporal.TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));val row=LinearLayout(a)
  (0..6).forEach { index->val day=monday.plusDays(index.toLong());val done=week.any { it.date==day };val rest=p.getBoolean("sports-recovery-$day",false);row.addView(text("${if(done)"✓" else if(rest)"R" else "○"}\n${day.dayOfWeek.name.take(3)}",if(compact)10f else 12f,if(done||rest)lime else muted).apply { gravity=Gravity.CENTER;contentDescription="$day ${if(done)"workout completed" else if(rest)"recovery completed" else "no recorded activity"}" },LinearLayout.LayoutParams(0,-2,1f)) };add(weekly,row)
  note(weekly,"${week.size} workouts · ${week.sumOf { it.timer.accumulated }/60000} active min\n${km(week.mapNotNull { it.distance }.takeIf { it.isNotEmpty() }?.sum())} · ${week.sumOf { it.repetitions }} repetitions\n${kcal(week.mapNotNull { it.calories }.takeIf { it.isNotEmpty() }?.sum())}")
  val quick=card("Quick Actions");listOf("Exercise Library" to "Exercises","Workout Plans" to "Plans","Activity History" to "Activity","Rest Day" to "Rest Day","Workout Statistics" to "Stats").forEach { (title,dest)->button(quick,"$title ›"){go(dest)} };commonTimer(page)
 }
 private fun gridExercises(parent:LinearLayout,exercises:List<ExerciseDefinition>){val columns=if(compact)1 else 2;exercises.chunked(columns).forEach { chunk->val row=LinearLayout(a);chunk.forEach { ex->val c=col().apply { background=bg();setPadding(dp(10),dp(10),dp(10),dp(10));isFocusable=true;contentDescription="Open ${ex.name}";setOnClickListener { go("Exercise:${ex.id}") } };art(c,ex.id,55);add(c,text(ex.name,15f,white,true));val records=repo.history().filter { it.date==today };val qty=if(ex.id in listOf("walking","jogging"))records.sumOf { exerciseDistance(it,ex.id)?:0.0 }/1000 else records.sumOf { s->s.items.filter { it.target.id==ex.id }.sumOf { it.repetitions } }.toDouble();note(c,if(ex.reps==0)"%.2f km logged today".format(qty) else "${qty.toInt()} reps today");bar(c,if(ex.reps>0)(qty*100/(target(ex.id).reps*target(ex.id).sets)).toInt() else (qty*100/5).toInt());note(c,if(ex.reps==0)"Reference goal: 5 km" else "Daily target: ${target(ex.id).reps*target(ex.id).sets} reps");button(c,"Start / Open",true){go("Exercise:${ex.id}")};row.addView(c,LinearLayout.LayoutParams(0,-2,1f).apply { setMargins(dp(3),0,dp(3),0) }) };if(chunk.size<columns)row.addView(View(a),LinearLayout.LayoutParams(0,1,1f));add(parent,row) } }
 private fun library(){val head=card("Exercise Library");val search=input(head,"Search exercises");val results=col();add(page,results);fun show(){results.removeAllViews();val found=SportsExercises.all.filter { it.name.contains(search.text.toString(),true) };if(found.isEmpty())note(results,"No matching exercises") else gridExercises(results,found)};search.addTextChangedListener(object:android.text.TextWatcher {override fun beforeTextChanged(s:CharSequence?,st:Int,c:Int,af:Int){};override fun onTextChanged(s:CharSequence?,st:Int,b:Int,c:Int){show()};override fun afterTextChanged(s:android.text.Editable?){} });show() }
 private fun target(id:String):PlannedExercise {val e=SportsExercises.get(id);return PlannedExercise(id,p.getInt("sports-target-$id-sets",e.sets),p.getInt("sports-target-$id-reps",e.reps),p.getInt("sports-target-$id-rest",e.rest),p.getInt("sports-target-$id-seconds",30),p.getString("sports-target-$id-mode","Reps")?:"Reps")}
 private fun exerciseSetup(id:String){val e=SportsExercises.get(id);val c=card(e.name);art(c,id,200);add(c,text(e.instructions,15f));val t=target(id);note(c,"${t.sets} sets × ${if(t.mode=="Timer")"${t.seconds} seconds" else "${t.reps} repetitions"} · ${t.rest}s rest");if(id in listOf("walking","jogging")){tabs(c,listOf("Outdoor GPS","Indoor / Manual","Treadmill"),p.getString("sports-mode-$id","Indoor / Manual")!!){p.edit().putString("sports-mode-$id",it).apply();refresh()};note(c,"Outdoor GPS requires location. Indoor / Manual and treadmill use elapsed time with optional measured distance and steps entered by you. No GPS is required indoors.") }else {button(c,"Adjust Sets, Reps & Rest"){editTarget(t){next->p.edit().putInt("sports-target-$id-sets",next.sets).putInt("sports-target-$id-reps",next.reps).putInt("sports-target-$id-rest",next.rest).putInt("sports-target-$id-seconds",next.seconds).putString("sports-target-$id-mode",next.mode).apply();refresh()}};if(id=="climbers")tabs(c,listOf("Reps","Timer"),t.mode){p.edit().putString("sports-target-$id-mode",it).apply();refresh()};performance(c,id) };if(id=="pushups"){val points=range(repo.history(),"Week").groupBy { it.date }.mapNotNull { (d,sessions)->val reps=sessions.flatMap { it.items }.filter { it.target.id=="pushups" }.flatMap { it.sets }.filter { !it.skipped };if(reps.isEmpty())null else ProgressPoint(d,reps.sumOf { it.reps }.toDouble()) }.sortedBy { it.date };if(points.isNotEmpty())c.addView(ProgressChart(a,points,"daily reps",lime),LinearLayout.LayoutParams(-1,dp(200))) else note(c,"Weekly push-up chart appears after your first saved workout.")};button(c,"Start ${e.name}",true){startExercise(t)}
 }
 private fun editTarget(t:PlannedExercise,save:(PlannedExercise)->Unit){dialog("Exercise targets"){c->val sets=input(c,"Sets (1–20)",t.sets.toString(),true);val reps=input(c,"Repetitions (1–1000)",t.reps.coerceAtLeast(1).toString(),true);val rest=input(c,"Rest seconds (10–600)",t.rest.toString(),true);val seconds=input(c,"Round duration seconds (5–600)",t.seconds.toString(),true);val action:()->Boolean={val st=sets.text.toString().toIntOrNull();val rp=reps.text.toString().toIntOrNull();val rs=rest.text.toString().toIntOrNull();val sec=seconds.text.toString().toIntOrNull();if(st==null||st !in 1..20||rp==null||rp !in 1..1000||rs==null||rs !in 10..600||sec==null||sec !in 5..600){toast("Check the target ranges");false}else{save(t.copy(sets=st,reps=rp,rest=rs,seconds=sec));true}};action } }
 private fun checkActive():Boolean {val active=repo.active()?:return false;AlertDialog.Builder(a).setTitle("A workout is already open").setMessage("Resume or save ${active.name} before starting another session.").setPositiveButton("Open workout"){_,_->go(if(active.status=="REVIEW")"Summary" else "Session")}.setNegativeButton("Cancel",null).show();return true}
 private fun startExercise(t:PlannedExercise){if(checkActive())return;val mode=if(t.id in listOf("walking","jogging"))p.getString("sports-mode-${t.id}","Indoor / Manual")!! else "Manual reps";if(mode=="Outdoor GPS"&&!hasLocation()){AlertDialog.Builder(a).setTitle("Allow outdoor location?").setMessage("Fit100 records GPS only during an active outdoor session and shows a persistent notification. Indoor / Manual works without location.").setNegativeButton("Use Indoor / Manual"){_,_->p.edit().putString("sports-mode-${t.id}","Indoor / Manual").apply();startExercise(t)}.setPositiveButton("Allow"){_,_->a.requestPermissions(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION),701)}.show();return};createSession(SportsExercises.get(t.id).name,listOf(t),mode) }
 private fun hasLocation()=a.checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||a.checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED
 private fun createSession(name:String,items:List<PlannedExercise>,mode:String){val n=now();val s=SportsSession(name=name,started=n.wall,items=items.map { SessionExercise(it) }.toMutableList(),mode=mode,weight=weight());SportsEngine.resume(s,n);repo.save(s);if(mode=="Outdoor GPS"||(items.firstOrNull()?.id in listOf("walking","jogging")&&sensorPermission()&&SportsStepMonitor(a).available()))SportsTrackingService.start(a);go("Session")}
 private fun sensorPermission()=Build.VERSION.SDK_INT<29||a.checkSelfPermission(Manifest.permission.ACTIVITY_RECOGNITION)==PackageManager.PERMISSION_GRANTED
 private fun startPlan(plan:SportsPlan){if(checkActive())return;if(plan.recovery){go("Rest Day");return};if(plan.exercises.isEmpty()){toast("Add exercises first");return};createSession(plan.name,plan.exercises,"Indoor / Manual")}
 private fun save(s:SportsSession){repo.save(s)}
 private fun tracker(){val s=repo.active();if(s==null){note(page,"No active workout. Choose an exercise or plan.");return};if(s.status=="REVIEW"){summary();return};val item=s.items.getOrNull(s.itemIndex)?:return;val id=item.target.id;val e=SportsExercises.get(id);val c=card(s.name);note(c,"Exercise ${s.itemIndex+1} of ${s.items.size} · ${e.name}");bar(c,s.completion);art(c,id,125);button(c,"Form Instructions"){AlertDialog.Builder(a).setTitle(e.name).setMessage(e.instructions).setPositiveButton("Done",null).show()}
  val time=text("",36f,lime,true).apply { gravity=Gravity.CENTER };add(c,time);live(time){duration((repo.session(s.id)?:s).timer.elapsed(now()))};val state=text("",14f,lime);add(c,state);live(state){val v=repo.session(s.id)?:s;"${v.status} · ${v.completedExercises}/${v.items.size} exercises · ${v.completion}%"}
  button(c,if(s.status=="PAUSED")"Resume Workout" else "Pause Workout",true){val v=repo.session(s.id)?:return@button;if(v.status=="ACTIVE"){SportsEngine.pause(v,now());save(v);a.stopService(Intent(a,SportsTrackingService::class.java))}else{if(v.mode=="Outdoor GPS"&&!hasLocation()){toast("Location access unavailable. Choose manual tracking.");return@button};SportsEngine.resume(v,now());save(v);if(v.mode=="Outdoor GPS"||(id in listOf("walking","jogging")&&sensorPermission()&&SportsStepMonitor(a).available()))SportsTrackingService.start(a)};SportsAlarms.schedule(a,"rest",v.rest);SportsAlarms.schedule(a,"round",v.items[v.itemIndex].round);refresh()}
  if(id in listOf("walking","jogging"))movement(c,s) else repetitions(c,s,item)
  commonTimer(c,s.id)
  if(s.items.size>1){button(c,"Next Exercise →"){val v=repo.session(s.id)?:return@button;if(!v.items[v.itemIndex].done){toast("Complete or skip remaining sets first");return@button};if(v.itemIndex<v.items.lastIndex){v.itemIndex++;if(v.status=="ACTIVE")v.items[v.itemIndex].timer.start(now());save(v);refresh()}else finish(v)};button(c,"Previous Exercise"){val v=repo.session(s.id)?:return@button;if(v.itemIndex>0){v.items[v.itemIndex].timer.pause(now());v.itemIndex--;save(v);refresh()}} }
  button(c,"Finish Exercise / Workout"){finish(repo.session(s.id)?:s)};button(c,"Discard Session"){confirm("Discard unsaved session?","This removes the current workout and its sets."){repo.delete(s.id);a.stopService(Intent(a,SportsTrackingService::class.java));go("Workout")}}
 }
 private fun movement(c:LinearLayout,s:SportsSession){val stats=text("",17f);add(c,stats);live(stats){val v=repo.session(s.id)?:s;val ms=v.timer.elapsed(now());val pace=if(v.distance!=null&&v.distance!!>10)duration((ms/(v.distance!!/1000)).toLong()).removePrefix("00:")+" /km" else "Unavailable";val speed=if(v.status=="ACTIVE"&&v.speed!=null&&v.route.lastOrNull()?.let { now().wall-it.wall<15000 }==true)"%.1f km/h".format(v.speed!!*3.6) else "Unavailable";"Steps: ${v.steps?.toString()?:"Unavailable"}\nDistance: ${km(v.distance)}\nAverage pace: $pace\nCurrent speed: $speed\n${kcal(SportsEngine.estimate(v,now()))}\nGPS: ${v.gpsStatus}\nElapsed since start: ${duration(now().wall-v.started)}"}
  note(c,"Active time excludes pauses. GPS distance uses reliable positions; indoor quantities can be entered manually.");button(c,"Enter Manual Distance / Steps"){manualMovement(s.id)}
  if(s.mode=="Outdoor GPS")button(c,"Switch to Indoor / Manual"){confirm("Use manual tracking?","GPS collection stops. Existing distance remains editable."){val v=repo.session(s.id)?:return@confirm;v.mode="Indoor / Manual";v.speed=null;v.gpsStatus="Manual entry";save(v);a.stopService(Intent(a,SportsTrackingService::class.java));refresh()}}
  if(s.route.size>1){note(c,"Recorded route · local coordinates");c.addView(SportsRouteArt(a,s.route),LinearLayout.LayoutParams(-1,dp(150)))}
  if(s.items.size>1)button(c,"Complete Walking / Jogging Segment"){val v=repo.session(s.id)?:return@button;v.items[v.itemIndex].done=true;v.items[v.itemIndex].timer.pause(now());save(v);refresh()}
 }
 private fun manualMovement(id:String){dialog("Manual activity entry"){c->val s=repo.session(id)!!;note(c,"Enter measured quantities. Manual steps add to daily sensor steps; do not re-enter observed sensor steps.");val distance=input(c,"Distance km (blank if unknown)",(s.distances?.get(s.itemIndex)?:s.distance?.takeIf { s.items.size==1 })?.let { "%.3f".format(java.util.Locale.US,it/1000) }?:"",true);val steps=input(c,"Steps (blank if unknown)",if(s.manualSteps)s.steps?.toString()?:"" else "",true);val action:()->Boolean={val raw=distance.text.toString();val d=raw.toDoubleOrNull();val sr=steps.text.toString();val st=sr.toIntOrNull();if((raw.isNotBlank()&&(d==null||!d.isFinite()||d !in 0.0..1000.0))||(sr.isNotBlank()&&(st==null||st !in 0..200000))){toast("Enter valid distance and steps");false}else{val v=repo.session(id)!!;v.mode="Indoor / Manual";val distances=v.distances?:mutableMapOf<Int,Double>().also { v.distances=it };if(d==null)distances.remove(v.itemIndex) else distances[v.itemIndex]=d*1000;v.distance=distances.values.takeIf { it.isNotEmpty() }?.sum();v.steps=st;v.manualSteps=true;v.gpsStatus="Manual entry";v.speed=null;save(v);a.stopService(Intent(a,SportsTrackingService::class.java));refresh();true}};action } }
 private fun repetitions(c:LinearLayout,s:SportsSession,e:SessionExercise){val counter=text("",25f,lime,true).apply { gravity=Gravity.CENTER };add(c,counter);live(counter){val ex=(repo.session(s.id)?:s).items[s.itemIndex];"Set ${(ex.sets.size+1).coerceAtMost(ex.target.sets)} / ${ex.target.sets}\n${ex.currentReps} / ${ex.target.reps} reps\n${ex.finishedSets} completed sets"}
  val roundMode=e.target.mode=="Timer";if(roundMode){val timer=text("",32f,lime,true);add(c,timer);live(timer){SportsAlarms.check(a,"round");duration((repo.session(s.id)?:s).items[s.itemIndex].round.remaining(now()))};button(c,"Start / Resume Round",true){val v=repo.session(s.id)?:return@button;val ex=v.items[v.itemIndex];if(v.status!="ACTIVE"||ex.done){toast("Resume workout or choose next exercise");return@button};if(ex.round.remaining(now())==0L||!ex.round.started)ex.round.begin(ex.target.seconds,now()) else ex.round.timer.start(now());save(v);SportsAlarms.schedule(a,"round",ex.round);refresh()} }
  fun mutate(change:(SportsSession,SessionExercise)->Unit){val v=repo.session(s.id)?:return;if(v.status!="ACTIVE"){toast("Resume workout first");return};val ex=v.items[v.itemIndex];if(ex.done){toast("Exercise complete");return};change(v,ex);save(v);refresh()}
  button(c,"+ Add Rep",true){mutate { _,ex->SportsEngine.rep(ex,1) }};button(c,"− Undo Rep"){mutate { _,ex->SportsEngine.rep(ex,-1) }}
  button(c,"Complete Set",true){mutate { v,ex->if(ex.currentReps==0&&(!roundMode||ex.round.timer.elapsed(now())<1000)){toast("Record reps or run round timer first")}else{SportsEngine.completeSet(v,false,now());SportsAlarms.schedule(a,"rest",v.rest)} }}
  button(c,"Skip Set"){confirm("Skip set?","Skipped sets are recorded and reduce completion."){mutate { v,_->SportsEngine.completeSet(v,true,now());SportsAlarms.schedule(a,"rest",v.rest) }}}
  e.sets.forEachIndexed { i,set->note(c,"Set ${i+1}: ${if(set.skipped)"Skipped" else "${set.reps} reps · ${set.seconds}s"}") };performance(c,e.target.id)
 }
 private fun performance(parent:LinearLayout,id:String){val all=repo.history();val sets=all.flatMap { s->s.items.filter { it.target.id==id }.flatMap { it.sets } };val best=sets.filter { !it.skipped }.maxOfOrNull { it.reps };val week=range(all,"Week").sumOf { s->s.items.filter { it.target.id==id }.sumOf { it.repetitions } };val prior=all.filter { it.date in today.minusDays(13)..today.minusDays(7) }.sumOf { s->s.items.filter { it.target.id==id }.sumOf { it.repetitions } };val previous=all.firstOrNull { s->s.items.any { it.target.id==id } };note(parent,"Personal best: ${best?.let { "$it reps / set" }?:"No record"}\nThis week: $week reps · Previous days 7–13: $prior reps\nPrevious workout: ${previous?.let { "${it.date} · ${it.items.filter { ex->ex.target.id==id }.sumOf { ex->ex.repetitions }} reps" }?:"No record"}") }
 private fun finish(s:SportsSession){confirm("Finish workout?","Completed sets are preserved. Uncompleted reps become a partial set. Review before saving."){s.items.forEach { e->if(e.currentReps>0){e.sets.add(SetRecord(reps=e.currentReps,at=now().wall));e.currentReps=0};if(e.target.id in listOf("walking","jogging"))e.done=true };SportsEngine.finish(s,now());save(s);a.stopService(Intent(a,SportsTrackingService::class.java));go("Summary")}}
 private fun summary(){val s=repo.active()?.takeIf { it.status=="REVIEW" };if(s==null){note(page,"No unsaved summary.");button(page,"View History"){go("Activity")};return};val c=card("Workout Summary");summaryContent(c,s);button(c,"Save Workout",true){val v=repo.session(s.id)?:return@button;if(v.status=="REVIEW")repo.complete(v);go("History:${s.id}")};button(c,"View History"){go("Activity")};button(c,"Return to Sports"){go("Workout")}}
 private fun summaryContent(c:LinearLayout,s:SportsSession){add(c,text(s.name,24f,lime,true));note(c,Instant.ofEpochMilli(s.started).atZone(ZoneId.systemDefault()).format(DateTimeFormatter.ofPattern("EEE, d MMM yyyy · HH:mm")));add(c,text("${duration(s.timer.accumulated)} active\n${s.completedExercises} / ${s.items.size} exercises\n${s.totalSets} sets · ${s.repetitions} repetitions\n${km(s.distance)} · ${s.steps?.toString()?:"—"} steps\n${kcal(calories(s))}\n${s.completion}% complete · ${s.status}",17f));bar(c,s.completion);s.items.forEach { ex->note(c,"${(SportsExercises.all.find { it.id==ex.target.id }?.name?:ex.target.id.removePrefix("legacy:"))}: ${ex.repetitions} reps · ${ex.finishedSets}/${ex.target.sets} sets");ex.sets.forEachIndexed { i,set->note(c,"  ${i+1}. ${if(set.skipped)"Skipped" else "${set.reps} reps · ${set.seconds}s"}") } };if(s.notes.isNotBlank())note(c,s.notes);note(c,"Calories are a MET estimate using saved session weight; no heart rate or camera counting is inferred.")}
 private fun plans(){val top=card("Weekly Workout Schedule");note(top,"Edit days, exercise order, targets and rest. Recovery days never demand intense training.");for(day in 1..7){val plan=repo.plan(day);val c=card("${DayOfWeek.of(day).name.lowercase().replaceFirstChar { it.uppercase() }} · ${plan.name}");note(c,if(plan.recovery)"Recovery / Rest" else "${plan.exercises.size} exercises");button(c,"Edit Day / Name"){dialog("Schedule settings"){form->val name=input(form,"Workout name",plan.name);val rest=CheckBox(a).apply { text="Recovery / Rest day";setTextColor(white);isChecked=plan.recovery };add(form,rest);val action:()->Boolean={if(name.text.isBlank()){name.error="Enter a name";false}else{plan.name=name.text.toString().take(80);plan.recovery=rest.isChecked;repo.plan(plan);refresh();true}};action }}
   plan.exercises.forEachIndexed { index,t->note(c,"${index+1}. ${SportsExercises.get(t.id).name} · ${t.sets} × ${if(t.mode=="Timer")"${t.seconds}s" else t.reps} · ${t.rest}s rest");button(c,"Edit ${index+1} · targets"){editTarget(t){next->plan.exercises[index]=next;repo.plan(plan);refresh()}};val row=LinearLayout(a);add(c,row);listOf("↑ Up","↓ Down","Remove").forEachIndexed { action,label->val b=Button(a).apply { text=label;isAllCaps=false;textSize=11f;setTextColor(white);background=bg();minimumHeight=dp(48);setOnClickListener { if(action==2)confirm("Remove exercise?",SportsExercises.get(t.id).name){plan.exercises.removeAt(index);repo.plan(plan);refresh()} else {val to=if(action==0)index-1 else index+1;if(to in plan.exercises.indices){java.util.Collections.swap(plan.exercises,index,to);repo.plan(plan);refresh()}else toast("Already at the ${if(action==0)"top" else "bottom"}") } } };row.addView(b,LinearLayout.LayoutParams(0,dp(48),1f)) } }
   button(c,"+ Add Exercise"){AlertDialog.Builder(a).setTitle("Choose exercise").setItems(SportsExercises.all.map { it.name }.toTypedArray()){_,i->plan.exercises.add(target(SportsExercises.all[i].id));repo.plan(plan);refresh()}.setNegativeButton("Cancel",null).show()};button(c,if(plan.recovery)"Start Recovery" else "Start ${plan.name}",true){startPlan(plan)}
  };button(top,"Copy a day to another weekday"){AlertDialog.Builder(a).setTitle("Copy from").setItems((1..7).map { DayOfWeek.of(it).name }.toTypedArray()){_,src->AlertDialog.Builder(a).setTitle("Copy to").setItems((1..7).map { DayOfWeek.of(it).name }.toTypedArray()){_,dest->val from=repo.plan(src+1);repo.plan(from.copy(day=dest+1,exercises=from.exercises.toMutableList()));refresh()}.show()}.show()}
 }
 private fun history(){val c=card("Activity History");val filter=p.getString("sports-history-range","This Week")!!;tabs(c,listOf("Today","This Week","All Time"),filter){p.edit().putString("sports-history-range",it).apply();refresh()};button(c,"Manual Activity Entry"){manualHistory()};val records=range(repo.history(),filter);if(records.isEmpty())note(c,"No completed activities in this range.");records.forEach { s->val entry=card(s.name);note(entry,"${s.date} · ${duration(s.timer.accumulated)}\n${s.totalSets} sets · ${s.repetitions} reps · ${km(s.distance)}\n${kcal(s.calories)} · ${s.completion}% complete");button(entry,"Review Session ›"){go("History:${s.id}")} } }
 private fun historyDetail(id:String){val s=repo.session(id);if(s==null){note(page,"Session no longer exists.");return};val c=card("Session Details");summaryContent(c,s);button(c,"Edit Session"){editHistory(s)};button(c,"Delete Session"){confirm("Delete session?","Permanently remove this workout and its sets from Sports statistics."){repo.delete(id);go("Activity")}};button(c,"View History"){go("Activity")};button(c,"Return to Sports"){go("Workout")} }
 private fun editHistory(s:SportsSession){dialog("Correct activity"){c->val name=input(c,"Workout name",s.name);val date=input(c,"Date (YYYY-MM-DD)",s.date.toString());val minutes=input(c,"Active minutes (0-1440)","%.2f".format(java.util.Locale.US,s.timer.accumulated/60000.0),true);val distance=input(c,"Distance km (optional)",s.distance?.let { "%.3f".format(java.util.Locale.US,it/1000) }?:"",true);val steps=input(c,"Manual steps (blank leaves source unchanged)",if(s.manualSteps)s.steps?.toString()?:"" else "",true);val notes=input(c,"Notes",s.notes)
 val corrections=mutableListOf<Triple<SessionExercise,Int,Pair<EditText,EditText>>>()
 s.items.forEach { ex->ex.sets.forEachIndexed { i,set->note(c,"${SportsExercises.all.find { it.id==ex.target.id }?.name?:ex.target.id} / Set ${i+1}${if(set.skipped)" (skipped)" else ""}");val reps=input(c,"Repetitions",set.reps.toString(),true);val sec=input(c,"Round seconds",set.seconds.toString(),true);corrections.add(Triple(ex,i,reps to sec)) } }
 val action:()->Boolean={val dt=runCatching { LocalDate.parse(date.text.toString()) }.getOrNull();val m=minutes.text.toString().toDoubleOrNull();val raw=distance.text.toString();val d=raw.toDoubleOrNull();val st=steps.text.toString().toIntOrNull();val validSets=corrections.all { (_,_,fields)->fields.first.text.toString().toIntOrNull()?.let { it in 0..10000 }==true&&fields.second.text.toString().toIntOrNull()?.let { it in 0..7200 }==true };if(name.text.isBlank()||dt==null||dt>today||m==null||!m.isFinite()||m !in 0.0..1440.0||(raw.isNotBlank()&&(d==null||!d.isFinite()||d !in 0.0..1000.0))||(steps.text.isNotBlank()&&(st==null||st !in 0..200000))||!validSets){toast("Check date and quantities");false}else{confirm("Apply corrections?","Analytics will use the edited values."){s.name=name.text.toString().take(80);s.timer.accumulated=(m*60000).toLong();s.distance=d?.times(1000);if(st!=null){s.steps=st;s.manualSteps=true};s.notes=notes.text.toString().take(2000);corrections.forEach { (ex,i,fields)->ex.sets[i]=ex.sets[i].copy(reps=fields.first.text.toString().toInt(),seconds=fields.second.text.toString().toInt()) };val at=dt.atTime(Instant.ofEpochMilli(s.started).atZone(ZoneId.systemDefault()).toLocalTime()).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();val changed=s.copy(started=at,ended=at+s.timer.accumulated);changed.distances=null;changed.calories=SportsEngine.estimate(changed,now());save(changed);refresh()};true}};action } }
 private fun manualHistory(){dialog("Log completed activity"){c->val type=Spinner(a).apply { adapter=ArrayAdapter(a,android.R.layout.simple_spinner_dropdown_item,SportsExercises.all.map { it.name }) };add(c,type);val date=input(c,"Date (YYYY-MM-DD)",today.toString());val minutes=input(c,"Active minutes (more than 0, up to 1440)","",true);val reps=input(c,"Total repetitions (optional)","",true);val distance=input(c,"Distance km (optional)","",true);val steps=input(c,"Manual steps (optional; do not repeat sensor steps)","",true);val notes=input(c,"Notes");val action:()->Boolean={val dt=runCatching { LocalDate.parse(date.text.toString()) }.getOrNull();val m=minutes.text.toString().toDoubleOrNull();val d=distance.text.toString().toDoubleOrNull();val rp=reps.text.toString().toIntOrNull();val st=steps.text.toString().toIntOrNull();if(dt==null||dt>today||m==null||!m.isFinite()||m<=0||m>1440||(distance.text.isNotBlank()&&(d==null||!d.isFinite()||d !in 0.0..1000.0))||(reps.text.isNotBlank()&&(rp==null||rp !in 0..100000))||(steps.text.isNotBlank()&&(st==null||st !in 0..200000))){toast("Check date and quantities");false}else{val ex=SportsExercises.all[type.selectedItemPosition];val item=SessionExercise(target(ex.id).copy(sets=1),done=true);if(rp!=null)item.sets.add(SetRecord(reps=rp,at=now().wall));val start=dt.atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli();val s=SportsSession(name=ex.name,started=start,ended=start+(m*60000).toLong(),status="REVIEW",timer=ActiveTimer(accumulated=(m*60000).toLong()),items=mutableListOf(item),distance=d?.times(1000),steps=st,weight=weight(),manualSteps=st!=null,notes=notes.text.toString().take(2000)+"\nManual entry; time of day not recorded.");s.calories=SportsEngine.estimate(s,now());repo.complete(s);refresh();true}};action } }
 private fun recovery(){val c=card("Recovery Today");add(c,text("Rest is part of progress",23f,lime,true));art(c,"walking",130);note(c,"Choose gentle movement that feels comfortable. Rest days are valid planned recovery.");listOf("Light walking (optional)","Gentle stretching","Mobility routine","Hydration reminder","Sleep routine").forEachIndexed { i,label->add(c,CheckBox(a).apply { text=label;setTextColor(white);buttonTintList=ColorStateList.valueOf(lime);isChecked=p.getBoolean("sports-recovery-$today-$i",false);setOnCheckedChangeListener { _,yes->p.edit().putBoolean("sports-recovery-$today-$i",yes).apply() } }) };button(c,"Record Sleep"){dialog("Sleep last night"){form->val sleep=input(form,"Hours slept (0–24)",p.getString("$today-sleep","")?:"",true);val action:()->Boolean={val h=sleep.text.toString().toDoubleOrNull();if(h==null||!h.isFinite()||h !in 0.0..24.0){sleep.error="Enter 0–24 hours";false}else{p.edit().putString("$today-sleep",h.toString()).apply();true}};action }};button(c,"Open Light Walking Tracker"){go("Exercise:walking")};button(c,"Mark Recovery Day Complete",true){p.edit().putBoolean("sports-recovery-$today",true).apply();SportsHub.changed();toast("Recovery recorded");refresh()};if(p.getBoolean("sports-recovery-$today",false))note(c,"✓ Today is recorded as planned recovery.");note(c,"Hydration: use your saved target and Home water tracker. You can use this timer for optional gentle stretching.");commonTimer(page) }
 private fun commonTimer(parent:LinearLayout,sessionId:String?=null){
  fun load()=sessionId?.let { repo.session(it)?.rest }?:repo.countdown()
  fun store(t:ExerciseCountdown){if(sessionId==null)repo.countdown(t) else repo.session(sessionId)?.let { it.rest=t;repo.save(it) }}
  val key=if(sessionId==null)"common" else "rest"
  val c=card(if(sessionId==null)"Exercise / Rest Timer" else "Rest Timer",parent);val display=text("",34f,lime,true).apply { gravity=Gravity.CENTER };add(c,display);live(display){SportsAlarms.check(a,key);duration(load().remaining(now()))};val presets=LinearLayout(a);add(c,presets)
  listOf(30,60,90,120).forEach { sec->presets.addView(Button(a).apply { text="${sec}s";textSize=12f;setTextColor(white);background=bg();setOnClickListener { val t=ExerciseCountdown(sec*1000L);store(t);SportsAlarms.schedule(a,key,t);refresh() } },LinearLayout.LayoutParams(0,dp(48),1f)) }
  button(c,"Start / Pause / Resume Rest",true){if(sessionId!=null&&repo.session(sessionId)?.status!="ACTIVE"){toast("Resume the workout first");return@button};val t=load();if(t.timer.running)t.timer.pause(now()) else if(t.remaining(now())==0L)t.begin((t.duration/1000).toInt().coerceAtLeast(1),now()) else {t.started=true;t.timer.start(now())};store(t);SportsAlarms.schedule(a,key,t);refresh()}
  button(c,"Reset Timer"){val t=load();t.timer.reset();t.notified=false;t.started=false;store(t);SportsAlarms.schedule(a,key,t);refresh()}
  listOf(-10,10).forEach { sec->button(c,if(sec>0)"+10 seconds" else "-10 seconds"){val t=load();t.adjust(sec,now());store(t);SportsAlarms.schedule(a,key,t);refresh()} }
 }
 private fun settings(){val c=card("Sports Settings");note(c,"${(1..7).count { !repo.plan(it).recovery }} scheduled workout days / week. Preferred time: ${p.getString("sports-preferred-time","17:00")}")
  button(c,"Default rest timer"){dialog("Rest timer preference"){form->val value=input(form,"Seconds (10-600)",p.getString("profile-timer","60")?:"60",true);val action:()->Boolean={val seconds=value.text.toString().toIntOrNull();if(seconds==null||seconds !in 10..600){value.error="Enter 10-600";false}else{p.edit().putString("profile-timer",seconds.toString()).apply();if(!repo.countdown().timer.running)repo.countdown(ExerciseCountdown(seconds*1000L));true}};action }}
  SportsExercises.all.filter { it.reps>0 }.forEach { exercise->button(c,"${exercise.name} targets"){editTarget(target(exercise.id)){t->p.edit().putInt("sports-target-${exercise.id}-sets",t.sets).putInt("sports-target-${exercise.id}-reps",t.reps).putInt("sports-target-${exercise.id}-rest",t.rest).putInt("sports-target-${exercise.id}-seconds",t.seconds).apply();refresh()}} }
button(c,"Daily step goal: ${p.getInt("sports-step-goal",10000)}"){dialog("Daily steps"){form->val value=input(form,"Goal (100–100000)",p.getInt("sports-step-goal",10000).toString(),true);val action:()->Boolean={val v=value.text.toString().toIntOrNull();if(v==null||v !in 100..100000){value.error="Enter 100–100000";false}else{p.edit().putInt("sports-step-goal",v).apply();refresh();true}};action }}
  val monitor=SportsStepMonitor(a);note(c,if(monitor.available())"Step sensor detected. Counts include observed steps after activation." else "Step sensor unavailable. You can log measured steps manually.")
  button(c,"Enable Step Sensor"){if(!monitor.available()){toast("No sensor. Use manual entry.");return@button};if(Build.VERSION.SDK_INT>=29&&!sensorPermission())AlertDialog.Builder(a).setTitle("Step sensor access").setMessage("Activity Recognition reads steps while Fit100 is open or a walking/jogging notification is active.").setNegativeButton("Use manual entry",null).setPositiveButton("Allow"){_,_->a.requestPermissions(arrayOf(Manifest.permission.ACTIVITY_RECOGNITION),702)}.show() else {p.edit().putBoolean("sports-step-enabled",true).apply();toast("Step access enabled");a.recreate()} }
  button(c,"Enable Timer Notifications"){if(Build.VERSION.SDK_INT>=33&&a.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)AlertDialog.Builder(a).setTitle("Timer notifications").setMessage("Allow alerts when rest and round timers finish with the screen locked.").setNegativeButton("Not now",null).setPositiveButton("Allow"){_,_->a.requestPermissions(arrayOf(Manifest.permission.POST_NOTIFICATIONS),703)}.show() else toast("Notification permission available")}
  add(c,Switch(a).apply { text="Optional timer sound";setTextColor(white);isChecked=p.getBoolean("sports-sound",false);setOnCheckedChangeListener { _,v->p.edit().putBoolean("sports-sound",v).apply() } });note(c,"Timers use monotonic elapsed time and restore after process recreation. Reboots pause running sessions at the last checkpoint. Android may delay alerts without exact-alarm access.")
  button(c,"Android Timer / Alarm Settings"){if(Build.VERSION.SDK_INT>=31)a.startActivity(Intent(android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,android.net.Uri.parse("package:${a.packageName}"))) else toast("Exact alarms supported")}
  button(c,"Body weight for calorie estimates"){dialog("Sports calorie estimate"){form->val weight=input(form,"Current weight kg (20–500)",p.getString("profile-currentweight","")?:"",true);val action:()->Boolean={val w=weight.text.toString().toDoubleOrNull();if(w==null||!w.isFinite()||w !in 20.0..500.0){weight.error="Enter 20–500 kg";false}else{p.edit().putString("profile-currentweight",w.toString()).apply();true}};action }}
 }
 private fun analytics(){val c=card("Workout Statistics");val filter=p.getString("sports-stats-range","Week")!!;tabs(c,listOf("Week","Month","All Time"),filter){p.edit().putString("sports-stats-range",it).apply();refresh()};val records=range(repo.history(),filter);val metrics=listOf("Daily steps","Walking distance","Jogging distance","Workout duration","Push-up improvement","Jumping-jack repetitions","Mountain-climber repetitions","Workout consistency","Estimated calories");val metric=p.getString("sports-stats-metric",metrics[0])!!;val spinner=Spinner(a).apply { adapter=ArrayAdapter(a,android.R.layout.simple_spinner_dropdown_item,metrics);setSelection(metrics.indexOf(metric).coerceAtLeast(0)) };add(c,spinner);spinner.onItemSelectedListener=object:AdapterView.OnItemSelectedListener {override fun onNothingSelected(parent:AdapterView<*>?){};override fun onItemSelected(parent:AdapterView<*>?,view:View?,pos:Int,id:Long){if(metrics[pos]!=metric){p.edit().putString("sports-stats-metric",metrics[pos]).apply();refresh()}}}
  val grouped=records.groupBy { it.date };val points=if(metric=="Workout consistency"){val recovery=p.all.filter { (key,value)->key.startsWith("sports-recovery-")&&value==true }.keys.mapNotNull { runCatching { LocalDate.parse(it.removePrefix("sports-recovery-")) }.getOrNull() }.filter { it<=today&&(filter=="All Time"||it>=(if(filter=="Week")today.with(java.time.temporal.TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY)) else today.minusDays(29))) };(records.map { it.date }+recovery).distinct().sorted().map { ProgressPoint(it,1.0) }}else if(metric=="Daily steps"){val dates=(p.all.keys.filter { it.startsWith("sports-sensor-") }.mapNotNull { runCatching { LocalDate.parse(it.removePrefix("sports-sensor-")) }.getOrNull() }+records.map { it.date }).distinct().filter { filter=="All Time"||it>=(if(filter=="Week")today.with(java.time.temporal.TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY)) else today.minusDays(29)) };dates.mapNotNull { d->SportsHub.dailySteps(a,d)?.let { ProgressPoint(d,it.toDouble()) } }.sortedBy { it.date }}else grouped.mapNotNull { (date,sessions)->val value:Double?=when(metric){"Walking distance","Jogging distance"->sessions.mapNotNull { exerciseDistance(it,if(metric=="Walking distance")"walking" else "jogging") }.takeIf { it.isNotEmpty() }?.sum()?.div(1000);"Workout duration"->sessions.sumOf { it.timer.accumulated }/60000.0;"Estimated calories"->sessions.mapNotNull { it.calories }.takeIf { it.isNotEmpty() }?.sum();"Workout consistency"->sessions.size.toDouble();else->{val ex=when(metric){"Push-up improvement"->"pushups";"Jumping-jack repetitions"->"jacks";else->"climbers"};val sets=sessions.flatMap { s->s.items.filter { it.target.id==ex } };if(sets.isEmpty())null else if(metric=="Push-up improvement")sets.flatMap { it.sets }.filter { !it.skipped }.maxOfOrNull { it.reps }?.toDouble() else sets.sumOf { it.repetitions }.toDouble()} };value?.let { ProgressPoint(date,it) } }.sortedBy { it.date }
  val unit=when(metric){"Daily steps"->"steps";"Walking distance","Jogging distance"->"km";"Workout duration"->"min";"Estimated calories"->"kcal est.";"Workout consistency"->"active / recovery days";else->"reps"};if(points.isEmpty())note(c,"No stored records for this metric and range. Complete a workout or log a measured activity to begin.") else {c.addView(ProgressChart(a,points,unit,lime),LinearLayout.LayoutParams(-1,dp(230)));note(c,"Tap a point to inspect date and value. Push-up improvement is the best completed-set reps per day.");points.forEach { point->note(c,"${point.date} · %.1f $unit".format(point.value)) }};button(c,"View Activity History"){go("Activity")}
 }
}

class SportsExerciseArt(c:Context,private val id:String):View(c){private val pen=Paint(Paint.ANTI_ALIAS_FLAG);init { contentDescription="${SportsExercises.get(id).name}: start and movement position illustration";importantForAccessibility=IMPORTANT_FOR_ACCESSIBILITY_YES }
 override fun onDraw(c:Canvas){val w=width.toFloat();val h=height.toFloat();pen.shader=LinearGradient(0f,0f,w,h,Color.rgb(28,54,36),Color.rgb(6,20,12),Shader.TileMode.CLAMP);c.drawRoundRect(0f,0f,w,h,18f,18f,pen);pen.shader=null;pen.color=Color.rgb(50,75,54);pen.strokeWidth=2f;c.drawLine(w*.05f,h*.85f,w*.95f,h*.85f,pen)
  for(pose in 0..1){c.save();c.translate(w*(if(pose==0).27f else .73f),h*.49f);val sc=min(w/230,h/120);c.scale(sc,sc);pen.color=if(pose==0)Color.rgb(210,227,214) else Color.rgb(156,255,69);pen.strokeWidth=7f;pen.strokeCap=Paint.Cap.ROUND;pen.style=Paint.Style.STROKE
   fun line(x:Float,y:Float,x2:Float,y2:Float){c.drawLine(x,y,x2,y2,pen)}
   if(id in listOf("pushups","knee","climbers")){val shift=if(pose==1)10f else 0f;c.drawCircle(-29f,-18f+shift,8f,pen);line(-19f,-15f+shift,10f,-4f);line(-17f,-12f+shift,-20f,20f);line(-20f,20f,-7f,20f);if(id=="knee"){line(10f,-4f,28f,20f);line(28f,20f,40f,10f)}else if(id=="climbers"&&pose==1){line(10f,-4f,-4f,13f);line(-4f,13f,10f,20f);line(10f,-4f,41f,20f)}else line(10f,-4f,41f,20f)
   }else {c.drawCircle(0f,-34f,8f,pen);line(0f,-23f,0f,6f);if(id=="jacks"&&pose==1){line(0f,-18f,-23f,-37f);line(0f,-18f,23f,-37f);line(0f,6f,-23f,36f);line(0f,6f,23f,36f)}else{val stride=if(pose==1)23f else 9f;line(0f,-18f,-18f,if(pose==1)-2f else 5f);line(0f,-18f,18f,if(pose==1)-25f else 5f);line(0f,6f,-stride,36f);line(0f,6f,stride,36f)} };c.restore() }
  pen.style=Paint.Style.FILL;pen.color=Color.rgb(156,255,69);pen.textSize=min(h*.14f,28f);pen.textAlign=Paint.Align.CENTER;c.drawText("→",w*.5f,h*.48f,pen)
 }
}
class SportsRouteArt(c:Context,private val points:List<RoutePoint>):View(c){private val pen=Paint(3);init {contentDescription="Recorded GPS route with ${points.size} accepted positions"};override fun onDraw(c:Canvas){if(points.size<2)return;val minX=points.minOf { it.lon };val minY=points.minOf { it.lat };val dx=(points.maxOf { it.lon }-minX).coerceAtLeast(.00001);val dy=(points.maxOf { it.lat }-minY).coerceAtLeast(.00001);val path=Path();points.forEachIndexed { i,p->val x=(12+(p.lon-minX)/dx*(width-24)).toFloat();val y=(height-12-(p.lat-minY)/dy*(height-24)).toFloat();if(i==0)path.moveTo(x,y) else path.lineTo(x,y) };pen.color=Color.rgb(156,255,69);pen.style=Paint.Style.STROKE;pen.strokeWidth=5f;c.drawPath(path,pen)} }
